// Lexicon Track C7c: the drink calculator's "last checked" line, read from the package statements.
// Soli Deo Gloria.
//
// The read model (assets/data/lexicon/calculator-checked.json) is generated by admin/lexicon/package-statements.mjs;
// that it is current is pinned by lexicon-package-statements.test.mjs ("exactly what the files say"). This file pins
// what the page may say with it: a date only beside the price the record holds, "may be out of date" once the record
// says so, and nothing at all for a disputed, missing or edited price.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (rel) => readFileSync(path.join(ROOT, rel), 'utf8');
const SRC = read('assets/js/calculator-checked.js');
const MODEL = JSON.parse(read('assets/data/lexicon/calculator-checked.json'));
const CONFIG = JSON.parse(read('assets/data/calculator-config.json'));

/** Load the script into a sandbox with a minimal document; returns its api and the card elements. */
function load({ lineId = 'royal-caribbean', pkg = {}, fetchJson = MODEL } = {}) {
  const els = {};
  for (const k of ['soda', 'refresh', 'deluxe']) {
    els[k] = {
      textContent: 'stale text from before', hidden: false, attrs: {},
      setAttribute(n, v) { this.attrs[n] = String(v); }, removeAttribute(n) { delete this.attrs[n]; },
    };
  }
  const listeners = {};
  const window = {
    ITW_LINE_CONFIG: lineId ? { id: lineId } : null,
    ITW: { store: { get: (k) => (k === 'economics' ? { pkg } : null) } },
    addEventListener: (ev, fn) => { (listeners[ev] ??= []).push(fn); },
  };
  const document = { querySelector: (sel) => els[(/data-checked="([a-z]+)"/.exec(sel) || [])[1]] ?? null };
  const fetch = async () => ({ ok: fetchJson !== null, json: async () => fetchJson });
  vm.runInNewContext(SRC, { window, document, fetch, Promise, Date, Object, Math, Number, isFinite });
  return { api: window.ITW_CHECKED, els, listeners, window };
}

const entry = {
  package: 'package:x.y', name: 'Y', shown: 14, includes_gratuity: false, disputed: false, price_per_day: 16.52,
  gratuity_rate: 0.18, checked: '2026-09-01', stale_after: '2026-11-30T00:00:00.000Z',
  rate_checked: '2026-04-14', rate_stale_after: '2026-07-13T00:00:00.000Z', statements: { price: 'env-0000000000000000' },
};
const ms = (iso) => Date.parse(iso);

test('a fresh record shows the date it was last checked', () => {
  const { api } = load();
  const fresh = { ...entry, rate_checked: '2026-09-01', rate_stale_after: '2026-11-30T00:00:00.000Z' };
  const n = api.note(fresh, 14, ms('2026-10-01T00:00:00Z'));
  assert.equal(n.state, 'fresh');
  assert.equal(n.text, 'Price last checked September 1, 2026.');
});

test('past its window the price says it may be out of date; the last fresh instant is still fresh', () => {
  const { api } = load();
  assert.equal(api.note(entry, 14, ms('2026-11-30T00:00:00.000Z')).state, 'rests_on_stale');
  const n = api.note(entry, 14, ms('2026-11-30T00:00:00.001Z'));
  assert.equal(n.state, 'stale');
  assert.match(n.text, /^Price last checked September 1, 2026, so it may be out of date\. Confirm it in your cruise planner/);
});

test('a fresh price resting on a stale gratuity rate says the rate may have changed', () => {
  const { api } = load();
  const n = api.note(entry, 14, ms('2026-10-01T00:00:00Z'));
  assert.equal(n.state, 'rests_on_stale');
  assert.equal(n.text, 'Price last checked September 1, 2026. The 18% gratuity added to it was last checked April 14, 2026, so it may have changed.');
});

test('nothing is said for a disputed, missing, malformed or edited price', () => {
  const { api } = load();
  const now = ms('2026-10-01T00:00:00Z');
  assert.equal(api.note({ ...entry, disputed: true }, 14, now), null);
  assert.equal(api.note({ ...entry, disputed: undefined }, 14, now), null, 'only an explicit disputed:false may speak');
  assert.equal(api.note(null, 14, now), null);
  assert.equal(api.note(entry, 15, now), null, 'the reader changed the price');
  assert.equal(api.note(entry, 14.004, now)?.state, 'rests_on_stale', 'a rounding difference under a cent is the same price');
  assert.equal(api.note(entry, 14.01, now), null);
  assert.equal(api.note(entry, undefined, now), null);
  assert.equal(api.note({ ...entry, checked: 'April 14' }, 14, now), null);
  assert.equal(api.note({ ...entry, stale_after: 'never' }, 14, now), null);
  assert.equal(api.note(entry, 14, NaN), null);
  assert.equal(api.longDate('2026-13-01'), null);
  assert.equal(api.accept({ format: 'something-else', lines: {} }), null);
  assert.equal(api.accept({ format: 'itw-calculator-checked/1', lines: [] }), null);
});

test('every dated entry vouches only for the figure the calculator actually shows', () => {
  let dated = 0;
  for (const [key, line] of Object.entries(MODEL.lines)) {
    assert.ok(CONFIG.lines[key], `${key} is a calculator line`);
    for (const [tier, e] of Object.entries(line)) {
      assert.equal(e.shown, CONFIG.lines[key].packages[tier].priceMid, `${key}.${tier}`);
      if (e.disputed) { assert.equal(e.checked, undefined, `${key}.${tier}: a disputed figure carries no date`); continue; }
      dated += 1;
      const note = CONFIG.lines[key]._sources.note;
      assert.ok(note.includes(e.checked), `${key}.${tier}: checked ${e.checked} is the date its line note states`);
      assert.equal(e.includes_gratuity, CONFIG.lines[key].rules.gratuity === 0, `${key}.${tier}`);
    }
  }
  assert.ok(dated >= 15, `dated entries: ${dated}`);
});

test("on 2026-11-01 Royal Caribbean's cards say their April prices may be out of date", () => {
  const { api } = load();
  const rcl = MODEL.lines['royal-caribbean'];
  for (const [tier, card] of [['soda', 'soda'], ['refreshment', 'refresh'], ['deluxe', 'deluxe']]) {
    const n = api.note(rcl[tier], CONFIG.lines['royal-caribbean'].packages[tier].priceMid, ms('2026-11-01T12:00:00Z'));
    assert.equal(n.state, 'stale', card);
    assert.match(n.text, /^Price last checked April 14, 2026, so it may be out of date\./, card);
  }
});

test('render fills the cards with text only, hides an edited card, and empties all when the record is unreadable', async () => {
  const pkg = { soda: 14, refresh: 99, deluxe: 77 };
  const { api, els, listeners } = load({ pkg });
  await api.load();
  api.render();
  assert.equal(els.soda.hidden, false);
  assert.match(els.soda.textContent, /^Price last checked April 14, 2026/);
  assert.equal(els.soda.attrs['data-state'], 'stale');
  assert.equal(els.refresh.hidden, true, 'the reader edited this price');
  assert.equal(els.refresh.textContent, '');
  assert.equal(els.deluxe.hidden, false);
  assert.equal(listeners['itw:line-changed'].length, 1, 'a line switch re-renders');

  const broken = load({ pkg, fetchJson: { format: 'nope' } });
  await broken.api.load();
  broken.api.render();
  for (const k of ['soda', 'refresh', 'deluxe']) assert.equal(broken.els[k].hidden, true, `${k}: nothing is vouched for without the record`);

  const noLine = load({ pkg, lineId: null });
  await noLine.api.load();
  noLine.api.render();
  assert.equal(noLine.els.soda.hidden, true);

  const proto = load({ pkg, lineId: '__proto__' });
  await proto.api.load();
  proto.api.render();
  assert.equal(proto.els.soda.hidden, true, 'an inherited key is not a line');

  // A line or package present only through the prototype chain is not in the record.
  const inherited = { format: 'itw-calculator-checked/1', lines: Object.create({ 'royal-caribbean': MODEL.lines['royal-caribbean'] }) };
  const viaProto = load({ pkg, fetchJson: inherited });
  await viaProto.api.load();
  viaProto.api.render();
  assert.equal(viaProto.els.soda.hidden, true, 'an inherited line is not read');
  const inheritedTier = { format: 'itw-calculator-checked/1', lines: { 'royal-caribbean': Object.create({ soda: MODEL.lines['royal-caribbean'].soda }) } };
  const tierProto = load({ pkg, fetchJson: inheritedTier });
  await tierProto.api.load();
  tierProto.api.render();
  assert.equal(tierProto.els.soda.hidden, true, 'an inherited package is not read');
});

test('the script sets text only, and the page wires it before the UI layer and caches it offline', () => {
  for (const banned of ['innerHTML', 'outerHTML', 'insertAdjacentHTML', 'eval(', 'new Function', 'document.write']) {
    assert.ok(!SRC.includes(banned), banned);
  }
  const html = read('drink-calculator.html');
  for (const k of ['soda', 'refresh', 'deluxe']) assert.ok(html.includes(`<p class="tiny muted" data-checked="${k}" hidden></p>`), k);
  const checked = html.indexOf('/assets/js/calculator-checked.js');
  assert.ok(checked > 0 && checked < html.indexOf('/assets/js/calculator-ui-v2.js'));
  assert.match(read('assets/js/calculator-ui-v2.js'), /window\.ITW_CHECKED\.render\(\)/);
  for (const f of ['sw.js', 'precache-manifest.json']) {
    const s = read(f);
    assert.ok(s.includes('/assets/js/calculator-checked.js') && s.includes('/assets/data/lexicon/calculator-checked.json'), f);
  }
});
